const TREE_DSA_TOP_K_BRANCHES = 3;

const DSA_V6_KEEP_FRACTION = 0.5;

/**
 * Computes a new selector state after scoring branches and applying monotone guards.
 * - Score branches by cosine distance to the active branch's tail.
 * - Select top k, then add guards (open questions, failing tests, solver notes).
 * - Monotone: once locked in keptEver, branches never leave.
 */
function makeTreeDsaV6Selector(store: Store, agentDelta: AgentDelta): (branches: TreeNode[], active: TreeNode) => TreeNode[] {
  // On the first call, keptEver is empty; we lock in the initial high-scoring branches plus guards.
  // On subsequent calls, keptEver is frozen, then we add any newly-guarded branches.
  // The result: as guards fire on unfinished work, they freeze more branches, and the set only grows.
  // Outcome: after N turns, "almost all branches" are in keptEver, selector is inert.
  return (branches: TreeNode[], active: TreeNode) => {
    const keptEver = store.getNodeMetadata(active.id, 'dsa-v6-kept-ever') ?? new Set<string>();
    const topK = branches
      .sort((a, b) => /* cosine score */ 0) // placeholder
      .slice(0, TREE_DSA_TOP_K_BRANCHES);
    const guarded = new Set<string>([
      ...topK.map((b) => b.id),
      ...branches.filter((b) => b.meta_json.open_questions?.length > 0).map((b) => b.id),
      ...branches.filter((b) => b.meta_json.tests?.some((t) => t.status === 'failed')).map((b) => b.id),
      ...store.getNodeMetadata(active.id, 'solver-annotations')?.split(',') ?? [],
    ]);
    const result = mergeKeepSets(keptEver, guarded);
    store.setNodeMetadata(active.id, 'dsa-v6-kept-ever', result);
    return branches.filter((b) => result.has(b.id));
  };
}

function mergeKeepSets(prev: Set<string>, current: Set<string>): Set<string> {
  // monotone: union, never remove
  return new Set([...prev, ...current]);
}

